"""Mutually exclusive per-robot diagnoses from saved simulation evidence."""
from experiment import *
import numpy as np
from scipy.spatial import ConvexHull,QhullError
from scipy.optimize import nnls
from projection_adapter import constraints
from states import config,walls
from shared_control.hard_projection import HardProjectionConfig

def cone_escape(nominal,A):
    """Distance infimum to complement of the closed cone generated by -A.

    Lower-dimensional cones have zero distance to their complement. For
    full-dimensional cones, origin-incident convex-hull facets give its exact
    supporting hyperplanes. Boundary crossing is an infimum, not an attained
    minimum for an open complement.
    """
    u=np.asarray(nominal).ravel();generators=-np.asarray(A);d=len(u)
    if not len(generators):return dict(infimum=0.,direction=None,reason='empty_cone')
    _,membership_residual=nnls(generators.T,u,maxiter=10000)
    if membership_residual>1e-9*max(np.linalg.norm(u),1.):
        return dict(infimum=0.,direction=None,direction_in_mean_normal_frame=None,mean_normal_axis_defined=False,joint_dimension=d,reason='nominal_already_outside_cone_numerical_membership',membership_residual=float(membership_residual),membership_absolute_tolerance=1e-9*max(float(np.linalg.norm(u)),1.),attained=True)
    U,S,Vh=np.linalg.svd(generators,full_matrices=True);rank=int(np.sum(S>1e-9*max(S[0],1.)))
    if rank<d:
        direction=Vh[rank];dist=0.;reason='rank_deficient_cone_zero_infimum'
    else:
        pts=np.vstack([np.zeros((1,d)),generators/np.maximum(np.linalg.norm(generators,axis=1,keepdims=True),1e-30)])
        try:
            hull=ConvexHull(pts);facets=hull.equations[np.abs(hull.equations[:,-1])<1e-8,:-1]
        except QhullError as e:return dict(infimum=None,direction=None,rank=rank,reason='Qhull_failure',error=str(e)[:200])
        if not len(facets):return dict(infimum=None,direction=None,rank=rank,reason='cone_is_full_space')
        distances=-facets@u/np.linalg.norm(facets,axis=1);j=int(np.argmin(distances));dist=float(max(0,distances[j]));direction=facets[j]/np.linalg.norm(facets[j]);reason='origin_incident_supporting_facet'
    mean=A.mean(0);axisnorm=np.linalg.norm(mean)
    local=None
    if axisnorm>1e-12:
        basis=[mean/axisnorm]
        for v in np.eye(d):
            x=v.copy()
            for b in basis:x-=np.dot(x,b)*b
            if np.linalg.norm(x)>1e-10:basis.append(x/np.linalg.norm(x))
            if len(basis)==d:break
        local=(np.asarray(basis)@direction).tolist()
    return dict(infimum=dist,direction=direction.tolist(),direction_in_mean_normal_frame=local,mean_normal_axis_defined=bool(axisnorm>1e-12),rank=rank,joint_dimension=d,reason=reason,attained=False)

def diagnose(raw,z,W=5.,tau=.05):
    s=raw['case']['state'];c=config(s['scene'],s['N']);p=z['positions'];g=np.asarray(s['goals']);nom=z['nominal'];safe=z['safe'];active=json.loads(str(z['active_json']));T=len(nom)
    if raw['numerical_failure']:return ['unknown']*s['N']
    arrived=np.linalg.norm(p[-1]-g,axis=-1)<=c.goal_tolerance
    count=max(1,int(np.ceil(W/c.dt)));categories=[]
    for i in range(s['N']):
        if arrived[i]:categories.append('arrived');continue
        if raw['collision']:categories.append('collision');continue
        if T<count:categories.append('insufficient_window');continue
        trajectory=p[-count-1:,i];motion=np.linalg.norm(trajectory-trajectory[0],axis=-1).max();quiet=motion<c.agent_radius
        if quiet:
            changed=z['projection_rewrite'][-count:,i];nonzero=np.linalg.norm(nom[-count:,i],axis=-1)>1e-6
            good=changed&nonzero&(z['cone_residual'][-count:]<tau)
            if np.mean(good)>=.9:categories.append('filter_equilibrium_deadlock');continue
            blockers=any(k[0]=='pair' and i in k[1:] and arrived[k[2] if k[1]==i else k[1]] for rows in active[-count:] for k in rows)
            if blockers:categories.append('blocked_by_arrived');continue
            if np.mean(~nonzero)>=.9:categories.append('zero_nominal');continue
            categories.append('other_stationary')
        else:
            length=np.linalg.norm(np.diff(trajectory,axis=0),axis=-1).sum();displacement=np.linalg.norm(trajectory[-1]-trajectory[0])
            categories.append('oscillation' if length>5*displacement else 'slow_progress')
    return categories

def census(raw,z):
    cats=diagnose(raw,z)
    if 'filter_equilibrium_deadlock' not in cats:return []
    s=raw['case']['state'];c=config(s['scene'],s['N']);count=min(len(z['nominal']),int(np.ceil(5/c.dt)));rows=[]
    for t in range(len(z['nominal'])-count,len(z['nominal'])):
        snap=dict(positions=z['positions'][t],walls=walls(s['scene']),config=c.to_dict())
        A,l,kinds=constraints(snap,HardProjectionConfig());v=z['safe'][t].ravel();ids=np.flatnonzero(A@v-l<=1e-7)
        if z['cone_residual'][t]>=.05 or not len(ids):continue
        nom=z['nominal'][t].ravel()
        if np.linalg.norm(nom)<=1e-12:continue # zero-vector angles are undefined
        active=A[ids];labels=[kinds[i] for i in ids];participants=set();graph={i:set() for i in range(s['N'])}
        for k in labels:
            if k[0]=='pair':graph[k[1]].add(k[2]);graph[k[2]].add(k[1]);participants.update(k[1:])
            elif k[0]=='wall':participants.add(k[1])
        sizes=[];remaining=set(participants)
        while remaining:
            todo=[remaining.pop()];group=set(todo)
            while todo:
                linked=graph[todo.pop()]&remaining;remaining-=linked;group|=linked;todo.extend(linked)
            sizes.append(len(group))
        angle=np.arccos(np.clip(active@nom/np.maximum(np.linalg.norm(active,axis=1)*np.linalg.norm(nom),1e-30),-1,1))*180/np.pi
        escape=cone_escape(nom,active);local2=[];mean=active.mean(0).reshape(s['N'],2)
        direction=np.asarray(escape['direction']).reshape(s['N'],2) if escape.get('direction') is not None else None
        for i in range(s['N']):
            length=np.linalg.norm(mean[i]);axis=mean[i]/length if length>1e-12 else None
            local2.append(None if axis is None or direction is None else [float(direction[i]@axis),float(direction[i]@np.array([-axis[1],axis[0]]))])
        rows.append(dict(rollout_uid=raw['rollout_uid'],scene=s['scene'],controller=raw['case']['controller_payload']['nominal']['controller'],type=raw['case']['controller_payload']['nominal']['type_code'],step=t,active_constraints=labels,active_lower_bounds=l[ids].tolist(),safe_joint_speed_norm=float(np.linalg.norm(v)),maximum_agent_safe_speed=float(np.linalg.norm(z['safe'][t],axis=-1).max()),nominal_joint_speed_norm=float(np.linalg.norm(nom)),cluster_sizes=sizes,nominal_normal_angles_degrees=angle.tolist(),escape=escape,escape_direction_per_agent_mean_normal_frame=local2))
    return rows
